	struct net_buf *buf = pkt->buffer;
	size_t pkt_len = net_pkt_get_len(pkt);

	if (pkt_len < length) {
		return -EINVAL;
	}

	pkt_len -= length;

	while (buf) {
		if (buf->len >= pkt_len) {
			buf->len = pkt_len;

			if (buf->frags) {
				net_pkt_frag_unref(buf->frags);
				buf->frags = NULL;
			}

			break;
		}

		buf = buf->frags;
		pkt_len -= buf->len;
	}

	return 0;
}
```

and easy way to add unit tests for it."}

